import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Why does the adapter admin UI misbehave?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/04.fehlerbehebung/04.admin-oberflaeche.md"},"headers":[],"relativePath":"adapter/esphome/fehlerbehebung/admin-oberflaeche.md","filePath":"adapter/esphome/fehlerbehebung/admin-oberflaeche.md","lastUpdated":1795562976000}'),s={name:"adapter/esphome/fehlerbehebung/admin-oberflaeche.md"};function i(r,e,h,d,l,m){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="why-does-the-adapter-admin-ui-misbehave" tabindex="-1">Why does the adapter admin UI misbehave? <a class="header-anchor" href="#why-does-the-adapter-admin-ui-misbehave" aria-label="Permalink to &quot;Why does the adapter admin UI misbehave?&quot;">​</a></h1><p><a id="warning-esphome-has-invalid-jsonconfig"></a></p><h2 id="what-does-the-warning-esphome-has-an-invalid-jsonconfig-mean" tabindex="-1">What does the warning &quot;esphome has an invalid jsonConfig&quot; mean? <a class="header-anchor" href="#what-does-the-warning-esphome-has-an-invalid-jsonconfig-mean" aria-label="Permalink to &quot;What does the warning &quot;esphome has an invalid jsonConfig&quot; mean?&quot;">​</a></h2><p>The warning is harmless, you do not need to do anything. It comes from admin, which checks the description of the settings page, not from the running adapter. Settings are still saved, devices and dashboard work normally.</p><p>After <code>esphome has an invalid jsonConfig:</code> admin names the field it objects to (<code>instancePath</code>). Usually admin just does not know one property of the field, for example the free input next to a list for &quot;ESPHome Dashboard version&quot;, the dashboard address or &quot;Python version&quot;.</p><p>The adapter needs admin 7.8.20 or newer. With an older admin the page does not display correctly, so update admin first. If the dashboard does not start at the same time, this warning is not the cause: <a href="./dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Dashboard does not start</a>.</p><p><strong>See also:</strong> <a href="#save-buttons-active-layout-unusable">Save buttons active or layout unusable</a> · <a href="./../erste-schritte/installation#instance-stay-red-after-install">Instance stays red after install or update</a></p><p><a id="save-buttons-active-layout-unusable"></a></p><h2 id="why-are-save-buttons-active-or-the-layout-unusable-on-mobile" tabindex="-1">Why are save buttons active or the layout unusable on mobile? <a class="header-anchor" href="#why-are-save-buttons-active-or-the-layout-unusable-on-mobile" aria-label="Permalink to &quot;Why are save buttons active or the layout unusable on mobile?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',10)])])}const c=a(s,[["render",i]]);export{p as __pageData,c as default};
